// 两种来源具有互斥的明确字段集；JSON重复键和typed未知标签都不能改写来源种类。
#include "biological_control_origin.hpp"
#include "succession_personal_assets.hpp"
#include "family_projection.hpp"
#include "family_source_projection.hpp"
#include "resident/domains/interaction/interaction_projection.hpp"
#include "resident/domains/interaction/personal_dialogues/known_personal_dialogue_proof_codec.hpp"
#include "resident/storage/common_checkpoint.hpp"
#include <set>
namespace hanmo::resident {namespace {
using V=BoundaryValue;
// 引用格式仅作结构边界；Common分配与真实目录/出生依赖留给同候选业务纯读。
bool reference(const StableId& value){return !value.empty()&&value.size()<=256;}
std::set<StableId> keys(BiologicalChildOriginKind kind){std::set<StableId> result{"origin_kind","parent_actor_id","child_actor_id","source_available_tick"};if(kind==BiologicalChildOriginKind::installed_lineage)result.insert("original_catalog_actor_id");else if(kind==BiologicalChildOriginKind::recorded_birth){result.insert("birth_fact_id");result.insert("creation_fact_id");}return result;}
Status shape(const BiologicalControlOrigin& s){if(s.kind!=BiologicalChildOriginKind::installed_lineage&&s.kind!=BiologicalChildOriginKind::recorded_birth)return common_failure("UnknownBiologicalControlOriginKind");if(!reference(s.parent_actor_id)||!reference(s.child_actor_id)||s.parent_actor_id==s.child_actor_id||s.source_available_tick<0)return common_failure("InvalidBiologicalControlOrigin");if(s.kind==BiologicalChildOriginKind::installed_lineage){if(s.original_catalog_actor_id!=s.child_actor_id||!s.birth_fact_id.empty()||!s.creation_fact_id.empty()||s.source_available_tick!=0)return common_failure("InvalidBiologicalControlInstalledOrigin");}else if(!s.original_catalog_actor_id.empty()||!reference(s.birth_fact_id)||s.creation_fact_id!=s.child_actor_id)return common_failure("InvalidBiologicalControlBirthOrigin");const auto expected=keys(s.kind);if(!s.field_order.empty()&&(s.field_order.size()!=expected.size()||std::set<StableId>(s.field_order.begin(),s.field_order.end())!=expected))return common_failure("BoundaryFieldOrderMismatch");return common_success();}
StableId name(BiologicalChildOriginKind kind){return kind==BiologicalChildOriginKind::installed_lineage?"installed_lineage":kind==BiologicalChildOriginKind::recorded_birth?"recorded_birth":"";}
Outcome<BiologicalChildOriginKind> kind(const StableId& value){if(value=="installed_lineage")return {true,BiologicalChildOriginKind::installed_lineage,{}};if(value=="recorded_birth")return {true,BiologicalChildOriginKind::recorded_birth,{}};return {false,{},common_failure("UnknownBiologicalControlOriginKind").error};}
}
Outcome<BiologicalControlOrigin> decode_biological_control_origin(const BoundaryValue& v){try{
    auto unique=validate_succession_json_unique(v);if(!unique.ok)return {false,{},unique.error};using namespace boundary;auto selected=kind(get_string(v,"origin_kind","biological_control_origin"));if(!selected.ok)return {false,{},selected.error};BiologicalControlOrigin out;out.kind=selected.value;
    if(out.kind==BiologicalChildOriginKind::installed_lineage){fields(v,{"origin_kind","parent_actor_id","child_actor_id","original_catalog_actor_id","source_available_tick"},{},"biological_control_origin");out.original_catalog_actor_id=get_string(v,"original_catalog_actor_id","");}
    else{fields(v,{"origin_kind","parent_actor_id","child_actor_id","birth_fact_id","creation_fact_id","source_available_tick"},{},"biological_control_origin");out.birth_fact_id=get_string(v,"birth_fact_id","");out.creation_fact_id=get_string(v,"creation_fact_id","");}
    out.parent_actor_id=get_string(v,"parent_actor_id","");out.child_actor_id=get_string(v,"child_actor_id","");out.source_available_tick=get_int(v,"source_available_tick","");out.field_order=order(v);auto valid=shape(out);return valid.ok?Outcome<BiologicalControlOrigin>{true,std::move(out),{}}:Outcome<BiologicalControlOrigin>{false,{},valid.error};
}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status validate_biological_control_origin_shape(const BiologicalControlOrigin& s){return shape(s);}
Status emit_biological_control_origin_fields(ProjectionWriter& w,const BiologicalControlOrigin& s){auto valid=shape(s);if(!valid.ok)return w.reject(valid.error.original.code,"biological_control_origin");w.text("origin_kind",s.kind==BiologicalChildOriginKind::installed_lineage?"installed_lineage":"recorded_birth");w.field("parent_actor_id",s.parent_actor_id);w.field("child_actor_id",s.child_actor_id);if(s.kind==BiologicalChildOriginKind::installed_lineage)w.field("original_catalog_actor_id",s.original_catalog_actor_id);else{w.field("birth_fact_id",s.birth_fact_id);w.field("creation_fact_id",s.creation_fact_id);}w.field("source_available_tick",s.source_available_tick);return w.order_fields(s.field_order);}
BoundaryValue encode_biological_control_origin(const BiologicalControlOrigin& s){return family_projection::encode([&](auto& w){return emit_biological_control_origin_fields(w,s);});}
Status visit_biological_control_origin_checkpoint(CodecVisitor& c,BiologicalControlOrigin& s){if(!c.reading()){auto valid=shape(s);if(!valid.ok)return c.reject(valid.error.original.code);}auto tag=name(s.kind);c.field("origin_kind",tag);if(!c.status().ok)return c.status();auto selected=kind(tag);if(!selected.ok)return c.reject(selected.error.original.code);s.kind=selected.value;c.field("parent_actor_id",s.parent_actor_id);c.field("child_actor_id",s.child_actor_id);if(s.kind==BiologicalChildOriginKind::installed_lineage){if(c.reading()){s.birth_fact_id.clear();s.creation_fact_id.clear();}c.field("original_catalog_actor_id",s.original_catalog_actor_id);}else{if(c.reading())s.original_catalog_actor_id.clear();c.field("birth_fact_id",s.birth_fact_id);c.field("creation_fact_id",s.creation_fact_id);}c.field("source_available_tick",s.source_available_tick);common_checkpoint::strings(c,"field_order",s.field_order);if(!c.status().ok)return c.status();auto valid=shape(s);return valid.ok?c.status():c.reject(valid.error.original.code);}
}
